const raw = $json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : {};
const query = raw.query && typeof raw.query === 'object' ? raw.query : {};
const headers = raw.headers && typeof raw.headers === 'object' ? raw.headers : {};
const incoming = { ...raw, ...query, ...body };
const webhookSecret = $env.N8N_WEBHOOK_SECRET || '';
if (!webhookSecret) throw new Error('N8N_WEBHOOK_SECRET is required.');
const receivedSecret = incoming.webhook_secret || headers['x-bakery-webhook-secret'] || headers['X-Bakery-Webhook-Secret'] || '';
if (receivedSecret !== webhookSecret) throw new Error('Unauthorized webhook request.');
if (incoming.live_image === true || incoming.live_image === 'true') {
  throw new Error('live_image is not allowed in the content webhook. Approve the package first, then use the image generation webhook.');
}
const hasPlainRequest = Boolean(incoming.user_request || incoming.request || incoming.natural_request);
const required = ['product_name', 'content_type', 'image_type', 'image_style'];
const missing = hasPlainRequest ? [] : required.filter((key) => !incoming[key]);
if (missing.length) {
  throw new Error(`Missing content task fields: ${missing.join(', ')}. Send user_request in the webhook body or provide structured task fields.`);
}
const imageCount = Number(incoming.image_count || 3);
if (!Number.isInteger(imageCount) || imageCount < 1 || imageCount > 8) {
  throw new Error('image_count must be an integer between 1 and 8.');
}
return [{ json: {
  user_request: incoming.user_request || incoming.request || incoming.natural_request || '',
  execution_mode: incoming.execution_mode || 'dry-run',
  campaign_name: incoming.campaign_name || 'Webhook Bakery Content Operation',
  product_name: incoming.product_name || '',
  content_type: incoming.content_type || '',
  image_type: incoming.image_type || '',
  image_style: incoming.image_style || '',
  platforms: incoming.platforms || 'xiaohongshu,douyin',
  campaign_goal: incoming.campaign_goal || '',
  audience: incoming.audience || '',
  constraints: incoming.constraints || 'No fake price, inventory, sales volume, health claims, nutrition claims, official authorization, logo, trademark, or embedded text.',
  image_count: imageCount,
  skip_image: incoming.skip_image ?? false,
  live_image: false
} }];
